'use strict';

/**
* Evaluate the Sigmoid Linear Unit (SiLU) activation function.
*
* @module @stdlib/math/base/special/silu
*
* @example
* var silu = require( '@stdlib/math/base/special/silu' );
*
* var y = silu( 0.0 );
* // returns 0.0
*
* y = silu( 1.0 );
* // returns ~0.7311
*
* y = silu( -Infinity );
* // returns -0.0
*
* y = silu( Infinity );
* // returns Infinity
*
* y = silu( NaN );
* // returns NaN
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
